        code = event["code"]

        if reader not in readers:
            readers[reader] = {"total": 0, "books": {}}

        summary = readers[reader]
        summary["total"] += 1
        summary["books"][code] = summary["books"].get(code, 0) + 1

    result = []
    for reader, summary in readers.items():
        books = [
            {"code": code, "title": titles[code], "count": count}
            for code, count in summary["books"].items()
        ]
        result.append(
            {"reader": reader, "total": summary["total"], "books": books}
        )

    return result
