lt[1], bytearray([4, 4]))\\n        self.assertIsNot(result[0], result[1])\\n        self.assertIsNot(result[0], left)\\n        self.assertIsNot(result[1], right)\\n\\n    def test_output_is_independent_from_input_in_both_directions(self):\\n        source = bytearray([1, 2])\\n        result = xor_shared_buffers([source], b\\\"\\\\xff\\\")\\n        result[0][0] = 50\\n        self.assertEqual(source, bytearray([1, 2]))\\n        source[1] = 99\\n        self.assertEqual(result[0], bytearray([50, 0xFD]))\\n\\n    def test_empty_list_and_empty_buffers(self):\\n        empty_result = xor_shared_buffers([], b\\\"key\\\")\\n        self.assertEqual(empty_result, [])\\n        self.assertIsNot(empty_result, [])\\n\\n        empty_buffer = bytearray()\\n        result = xor_shared_buffers([empty_buffer, empty_buffer], b\\\"k\\\")\\n        self.assertEqual(result, [bytearray(), bytearray()])\\n        self.assertIs(result[0], result[1])\\n        self.assertIsNot(result[0], empty_buffer)\\n\\n    def test_byte_boundaries_with_single_byte_key(self):\\n        source = bytearray([0x00, 0xFF, 0x80, 0x7F])\\n        result = xor_shared_buffers([source], b\\\"\\\\xff\\\")\\n        self.assertEqual(result, [bytearray([0xFF, 0x00, 0x7F, 0x80])])\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main()\\n\"},{\"id\":\"cap-v2-binary_and_bitwise-python-repair-02\",\"test_code\":\"import unittest\\n\\nfrom solution import clear_register_bits\\n\\n\\nclass ClearRegisterBitsTests(unittest.TestCase):\\n    def test_clears_selected_bits_from_every_byte(self):\\n        registers = {\\n            \\\"control\\\": bytearray([0b11111111, 0b10101010]),\\n            \\\"status\\\": bytearray([0b01010101, 0b00001111]),\\n        }\\n        result = clear_register_bits(registers, 0b00110011)\\n        self.assertEqual(\\n            result,\\n            {\\n                \\\"control\\\": bytearray([0b11001100, 0b10001000]),\\n                \\\"status\\\": bytearray([0b01000100, 0b00001100]),\\n            },\\n        )\\n\\n    def test_input_dictionary_and_buffers_are_not_mutated(self):\\n        first = bytearray([0xFF, 0x12])\\n        second = bytearray([0x80])\\n        registers = {\\\"first\\\": first, \\\"second\\\": second}\\n        original_items = list(registers.items())\\n        original_contents = {key: bytes(value) for key, value in registers.items()}\\n\\n        result = clear_register_bits(registers, 0x0F)\\n\\n        self.assertEqual(list(registers.items()), original_items)\\n        self.assertEqual({key: bytes(value) for key, value in registers.items()}, original_contents)\\n        self.assertIsNot(result, registers)\\n        self.assertIsNot(result[\\\"first\\\"], first)\\n        self.assertIsNot(result[\\\"second\\\"], second)\\n\\n    def test_aliases_are_preserved_only_inside_result(self):\\n        shared = bytearray([0xFF, 0x5A])\\n        registers = {\\\"a\\\": shared, \\\"b\\\": shared}\\n        result = clear_register_bits(registers, 0x0F)\\n        self.assertIs(result[\\\"a\\\"], result[\\\"b\\\"])\\n        self.assertIsNot(result[\\\"a\\\"], shared)\\n        self.assertEqual(result[\\\"a\\\"], bytearray([0xF0, 0x50]))\\n        self.assertEqual(shared, bytearray([0xFF, 0x5A]))\\n\\n    def test_distinct_equal_buffers_remain_distinct(self):\\n        left = bytearray([0xAA])\\n        right = bytearray([0xAA])\\n        result = clear_register_bits({\\\"left\\\": left, \\\"right\\\": right}, 0x03)\\n        self.assertEqual(result[\\\"left\\\"], bytearray([0xA8]))\\n        self.assertEqual(result[\\\"right\\\"], bytearray([0xA8]))\\n        self.assertIsNot(result[\\\"left\\\"], result[\\\"right\\\"])\\n        self.assertIsNot(result[\\\"left\\\"], left)\\n        self.assertIsNot(result[\\\"right\\\"], right)\\n\\n    def test_zero_mask_copies_without_changing_values(self):\\n        source = bytearray([0x00, 0x7F, 0xFF])\\n        result = clear_register_bits({\\\"r\\\": source}, 0)\\n        self.assertEqual(result[\\\"r\\\"], source)\\n        self.assertIsNot(result[\\\"r\\\"], source)\\n\\n    def test_full_mask_clears_every_bit(self):\\n        source = bytearray([0x00, 0x01, 0x80, 0xFF])\\n        result = clear_register_bits({\\\"r\\\": source}, 255)\\n        self.assertEqual(result[\\\"r\\\"], bytearray([0, 0, 0, 0]))\\n        self.assertEqual(source, bytearray([0x00, 0x01, 0x80, 0xFF]))\\n\\n    def test_empty_mapping_and_empty_aliased_buffers(self):\\n        empty_result = clear_register_bits({}, 0x55)\\n        self.assertEqual(empty_result, {})\\n\\n        empty = bytearray()\\n        result = clear_register_bits({\\\"x\\\": empty, \\\"y\\\": empty}, 0xFF)\\n        self.assertIs(result[\\\"x\\\"], result[\\\"y\\\"])\\n        self.assertIsNot(result[\\\"x\\\"], empty)\\n\\n    def test_result_and_input_are_independent_after_return(self):\\n        source = bytearray([0xFF])\\n        result = clear_register_bits({\\\"r\\\": source}, 0x0F)\\n        result[\\\"r\\\"][0] = 1\\n        self.assertEqual(source, bytearray([0xFF]))\\n        source[0] = 2\\n        self.assertEqual(result[\\\"r\\\"], bytearray([1]))\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main()\\n\"},{\"id\":\"cap-v2-callbacks_and_events-python-generation-01\",\"test_code\":\"import unittest\\n\\nfrom solution import dispatch_records\\n\\n\\nclass StringSubclass(str):\\n    pass\\n\\n\\nclass IntSubclass(int):\\n    pass\\n\\n\\nclass TupleSubclass(tuple):\\n    pass\\n\\n\\nclass DispatchRecordsTests(unittest.TestCase):\\n    def make_callbacks(self, calls):\\n        def on_record(name, value):\\n            calls.append((\\\"record\\\", name, value))\\n\\n        def on_invalid(index, value):\\n            calls.append((\\\"invalid\\\", index, value))\\n\\n        def on_complete(valid_count, invalid_count):\\n            calls.append((\\\"complete\\\", valid_count, invalid_count))\\n\\n        return on_record, on_invalid, on_complete\\n\\n    def test_processes_valid_and_malformed_values_in_order(self):\\n        malformed_list = [\\\"bad\\\", 3]\\n        records = [\\n            (\\\"alpha\\\", 1),\\n            malformed_list,\\n            (\\\"beta\\\", -7),\\n            (\\\"\\\", 4),\\n            (\\\"gamma\\\", 0),\\n        ]\\n        calls = []\\n        callbacks = self.make_callbacks(calls)\\n        result = dispatch_records(records, *callbacks)\\n        self.assertIsNone(result)\\n        self.assertEqual(\\n            calls,\\n            [\\n                (\\\"record\\\", \\\"alpha\\\", 1),\\n                (\\\"invalid\\\", 1, malformed_list),\\n                (\\\"record\\\", \\\"beta\\\", -7),\\n                (\\\"invalid\\\", 3, (\\\"\\\", 4)),\\n                (\\\"record\\\", \\\"gamma\\\", 0),\\n                (\\\"complete\\\", 3, 2),\\n            ],\\n        )\\n\\n    def test_empty_input_still_completes_once(self):\\n        calls = []\\n        callbacks = self.make_callbacks(calls)\\n        self.assertIsNone(dispatch_records([], *callbacks))\\n        self.assertEqual(calls, [(\\\"complete\\\", 0, 0)])\\n\\n    def test_exact_types_are_required(self):\\n        values = [\\n            (\\\"ok\\\", 10),\\n            (StringSubclass(\\\"name\\\"), 1),\\n            (\\\"bool-is-not-exact-int\\\", True),\\n            (\\\"int-subclass\\\", IntSubclass(2)),\\n            TupleSubclass((\\\"tuple-subclass\\\", 3)),\\n        ]\\n        calls = []\\n        callbacks = self.make_callbacks(calls)\\n        dispatch_records(values, *callbacks)\\n        self.assertEqual(calls[0], (\\\"record\\\", \\\"ok\\\", 10))\\n        self.assertEqual([call[0] for call in calls[1:5]], [\\\"invalid\\\"] * 4)\\n        self.assertEqual([call[1] for call in calls[1:5]], [1, 2, 3, 4])\\n        for offset, call in enumerate(calls[1:5], start=1):\\n            self.assertIs(call[2], values[offset])\\n        self.assertEqual(calls[-1], (\\\"complete\\\", 1, 4))\\n\\n    def test_tuple_shape_and_name_rules(self):\\n        malformed = [\\n            (),\\n            (\\\"one\\\",),\\n            (\\\"three\\\", 1, 2),\\n            [\\\"list\\\", 1],\\n            (123, 4),\\n            (None, 5),\\n            (\\\"\\\", 6),\\n        ]\\n        calls = []\\n        callbacks = self.make_callbacks(calls)\\n        dispatch_records(malformed, *callbacks)\\n        self.assertEqual(len(calls), 8)\\n        for index, value in enumerate(malformed):\\n            self.assertEqual(calls[index][0:2], (\\\"invalid\\\", index))\\n            self.assertIs(calls[index][2], value)\\n        self.assertEqual(calls[-1], (\\\"complete\\\", 0, 7))\\n\\n    def test_large_exact_integers_and_input_stability(self):\\n        records = [(\\\"low\\\", -(10 ** 40)), (\\\"high\\\", 10 ** 40)]\\n        snapshot = list(records)\\n        calls = []\\n        callbacks = self.make_callbacks(calls)\\n        dispatch_records(records, *callbacks)\\n        self.assertEqual(records, snapshot)\\n        self.assertEqual(\\n            calls,\\n            [\\n                (\\\"record\\\", \\\"low\\\", -(10 ** 40)),\\n                (\\\"record\\\", \\\"high\\\", 10 ** 40),\\n                (\\\"complete\\\", 2, 0),\\n            ],\\n        )\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main()\\n\"},{\"id\":\"cap-v2-callbacks_and_events-python-generation-02\",\"test_code\":\"import unittest\\n\\nfrom solution import broadcast_events\\n\\n\\nclass StringSubclass(str):\\n    pass\\n\\n\\nclass TupleSubclass(tuple):\\n    pass\\n\\n\\nclass BroadcastEventsTests(unittest.TestCase):\\n    def test_listener_order_event_order_counts_and_final_completion(self):\\n        calls = []\\n\\n        def first(payload):\\n            calls.append((\\\"first\\\", payload))\\n\\n        def second(payload):\\n            calls.append((\\\"second\\\", payload))\\n\\n        def other(payload):\\n            calls.append((\\\"other\\\", payload))\\n\\n        def on_invalid